"use strict";const n=require("../common/vendor.js");exports.hideLoading=function(){n.index.hideLoading()},exports.isValidPassword=function(n){return n&&n.length>=6},exports.isValidPhone=function(n){return/^1[3-9]\d{9}$/.test(n)},exports.maskPhone=function(n){return!n||n.length<7?n||"":n.slice(0,3)+"****"+n.slice(-4)},exports.navigateBack=function(e=1){n.index.navigateBack({delta:e})},exports.navigateTo=function(e,t={}){const o=Object.keys(t).map(n=>`${n}=${t[n]}`).join("&");n.index.navigateTo({url:o?`${e}?${o}`:e})},exports.redirectTo=function(e,t={}){const o=Object.keys(t).map(n=>`${n}=${t[n]}`).join("&");n.index.redirectTo({url:o?`${e}?${o}`:e})},exports.showLoading=function(e="加载中..."){n.index.showLoading({title:e,mask:!0})},exports.showToast=function(e,t="none"){n.index.showToast({title:e,icon:t,duration:2e3})},exports.switchTab=function(e){n.index.switchTab({url:e})};
